            "%.2f" % best_d,
            target_ids=[best["object_id"]],
            evidence=[
                "list_objects returned centroid_m for all objects; distance to camera = euclidean norm of centroid_m",
                "farthest object: %s (%s) at %.3f m" % (best["object_id"], best["label"], best_d),
            ],
        )

