def _val(res):
    if not res.ok:
        return None
    return res.value

def _dist_to_cam(obj):
    c = obj.get("centroid_m")
    if c is None:
        return None
    return (c[0] ** 2 + c[1] ** 2 + c[2] ** 2) ** 0.5

sofa_res = single_object(scene_id="probe_scene", label="sofa")
mirror_res = single_object(scene_id="probe_scene", label="mirror")

sofa = _val(sofa_res)
mirror = _val(mirror_res)

if sofa is None or mirror is None:
    submit("unknown", evidence=["sofa or mirror not found in scene"])

ds = _dist_to_cam(sofa)
dm = _dist_to_cam(mirror)

if ds is None or dm is None:
    submit("unknown", evidence=["missing centroid_m for sofa or mirror"])

if ds > dm:
    ans = "sofa"
else:
    ans = "mirror"

submit(
    ans,
    target_ids=[sofa["object_id"], mirror["object_id"]],
    evidence=[
        "distance from camera = ||centroid_m||; sofa centroid=%s -> %.3f m" % (sofa["centroid_m"], ds),
        "mirror centroid=%s -> %.3f m" % (mirror["centroid_m"], dm),
        "larger norm means farther from camera",
    ],
)

